mapper.update:
UPDATE imports
SET status = #{status}, source_id = #{sourceId,jdbcType=OTHER}, read_at = #{at},
    storage_key = NULL, error_code = NULL, updated_at = #{at}
WHERE id = #{id}

UPDATE imports
SET status = 'QUEUED', attempts = attempts + 1, error_code = NULL, updated_at = #{at}
WHERE id = #{id} AND user_id = #{userId} AND status = 'FAILED' AND storage_key IS NOT NULL

UPDATE imports
SET status = 'SAVED', reviewed_at = coalesce(reviewed_at, #{at}), updated_at = #{at}
WHERE id = #{id}

UPDATE import_marks
SET save_id = #{saveId,jdbcType=OTHER}, color = #{color}, selected = #{selected}
WHERE id = #{id}
